// frontend/src/components/Dashboard.jsx

import React, { useEffect, useState, useRef } from "react";
import { io } from "socket.io-client";
import { fetchStats, fetchFraudCycles, fetchRiskLogs, fetchTraders } from "../services/api";
import GraphView from "../components/GraphView";
import FraudTable from "../components/FraudTable";
import TraderCard from "../components/TraderCard";
import RiskHeatmap from "../components/RiskHeatmap";
import InsertTradeForm from "../components/InsertTradeForm";

const SOCKET_URL = "http://localhost:5000";

export default function Dashboard() {
  const [stats, setStats] = useState(null);
  const [cycles, setCycles] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [traders, setTraders] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [flashRed, setFlashRed] = useState(false);
  const socketRef = useRef(null);

  useEffect(() => {
    fetchStats().then(setStats);
    fetchFraudCycles().then((d) => setCycles(d.cycles || []));
    fetchRiskLogs().then(setRiskLogs);
    fetchTraders().then(setTraders);

    socketRef.current = io(SOCKET_URL);
    socketRef.current.on("fraud_alert", (newAlerts) => {
      setAlerts((prev) => [...newAlerts, ...prev].slice(0, 10));
      setFlashRed(true);
      setTimeout(() => setFlashRed(false), 2000);
    });
    return () => socketRef.current?.disconnect();
  }, []);

  return (
    <div className="relative min-h-screen text-white pb-20">
      {/* Dynamic Red Glow on Alert */}
      <div 
        className="absolute inset-0 pointer-events-none transition-opacity duration-500"
        style={{ 
          background: "radial-gradient(circle at top, rgba(255,0,51,0.15) 0%, transparent 70%)",
          opacity: flashRed ? 1 : 0 
        }}
      />

      {alerts.length > 0 && (
        <div className="glass border-[#FF0033]/50 bg-[#FF0033]/10 p-4 mb-8 rounded-xl flex items-center gap-4 animate-pulse">
          <span className="w-3 h-3 rounded-full bg-[#FF0033] shadow-crimson"></span>
          <p className="m-0 text-[#FF0033] font-bold tracking-wider">
            SYSTEM ALERT: <span className="text-white font-normal">{alerts[0]?.reason}</span>
          </p>
        </div>
      )}

      {/* Stats Grid */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
          {[
            { label: "Total Trades", value: stats.total_trades },
            { label: "High Risk Trades", value: stats.high_risk_trades, alert: true },
            { label: "High Risk Traders", value: stats.high_risk_traders, alert: true },
            { label: "Total Fraud Logs", value: stats.total_fraud_logs },
          ].map((s) => (
            <div key={s.label} className="glass p-6 hover:border-[#00FF66]/30 transition-colors">
              <p className="text-gray-400 text-xs font-bold uppercase tracking-widest mb-2">{s.label}</p>
              <h2 className={`text-4xl font-black ${s.alert && s.value > 0 ? 'text-[#FF0033] drop-shadow-crimson' : 'neon-text'}`}>
                {s.value}
              </h2>
            </div>
          ))}
        </div>
      )}

      {/* Graph Section */}
      <div className="mb-12">
        <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
          <span className="text-[#00FF66]">◉</span> Live Network Topology
        </h2>
        <div className="glass p-1">
          {cycles.length > 0 ? <GraphView cycles={cycles} /> : (
            <div className="py-20 text-center text-gray-500 font-mono">No active anomalies detected.</div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-12">
        <div className="lg:col-span-2">
          <h2 className="text-2xl font-bold mb-6">Recent Risk Logs</h2>
          <div className="glass p-6 overflow-x-auto"><FraudTable logs={riskLogs.slice(0, 10)} /></div>
        </div>
        <div>
          <h2 className="text-2xl font-bold mb-6">Live Injection</h2>
          <InsertTradeForm onInserted={() => fetchStats().then(setStats)} />
        </div>
      </div>

      <h2 className="text-2xl font-bold mb-6">Entity Risk Distribution</h2>
      <div className="glass p-6"><RiskHeatmap /></div>
    </div>
  );
}
